```yaml
name: Check SLO Label Removal

on:
  workflow_run:
    workflows: ["SLO"]
    types:
      - completed

permissions:
  contents: read
  issues: write

jobs:
  remove-slo-label:
    runs-on: ubuntu-latest
    if: ${{ always() }}
    steps:
      - name: Remove SLO label from PR
        uses: actions/github-script@v7
        with:
          script: |
            const prNumber = context.payload.workflow_run.pull_requests[0]?.number;
            if (!prNumber) {
              console.log('No pull request found in workflow run.');
              return;
            }
            const label = 'SLO';
            try {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                name: label
              });
              console.log(`Removed label ${label} from PR #${prNumber}`);
            } catch (error) {
              if (error.status === 404) {
                console.log(`Label ${label} not found on PR #${prNumber}`);
              } else {
                throw error;
              }
            }
